anchor="function mse_delq(string $sql,array $a,array &$o,string $key): void"
insert="""function mse_valid_time(string $t): ?string {$t=trim($t);if($t==='')return null;if(!preg_match('/^(?:[01]\\d|2[0-3]):[0-5]\\d$/',$t))throw new RuntimeException('Horário inválido. Use HH:MM.');return$t.':00';}\nfunction mse_edit_group(string $ig,string $date,?string $cultoId,string $newDate,string $newName,?string $newTime,array $before): array {$newName=trim($newName);if($newName==='')throw new RuntimeException('Informe o nome da escala/culto.');$oldName=trim((string)($before['culto_nome']??''));$oldTime=substr((string)($before['horario']??''),0,5);$newHm=$newTime?substr($newTime,0,5):'';$clone=$cultoId===null||$cultoId===''||$newName!==$oldName||$newHm!==$oldTime;$target=$cultoId;$pdo=db();$pdo->beginTransaction();try{if($clone){$target=uuid4();$q=$pdo->prepare(\"INSERT INTO cultos(created_at,dia_semana,horario,id,igreja_id,nome,recorrente) VALUES(NOW(),NULL,?,?,?,?,0)\");$q->execute([$newTime,$target,$ig,$newName]);}elseif($newDate!==$date){$a=[$ig,$newDate];$w=\"BINARY igreja_id=BINARY ? AND data=?\";if($target===null||$target==='')$w.=\" AND culto_id IS NULL\";else{$w.=\" AND BINARY culto_id=BINARY ?\";$a[]=$target;}$q=$pdo->prepare(\"SELECT COUNT(*) FROM escalas WHERE {$w}\");$q->execute($a);if((int)$q->fetchColumn()>0)throw new RuntimeException('Já existe uma escala desse culto na nova data.');}$a=[];$w=mse_group_where($ig,$date,$cultoId,$a);$sql=$clone?\"UPDATE escalas e SET e.data=?,e.culto_id=? WHERE {$w}\":\"UPDATE escalas e SET e.data=? WHERE {$w}\";$args=$clone?array_merge([$newDate,$target],$a):array_merge([$newDate],$a);$q=$pdo->prepare($sql);$q->execute($args);$n=$q->rowCount();if($n<1)throw new RuntimeException('A escala selecionada não existe mais. Atualize a lista.');$pdo->commit();}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}$after=mse_one($ig,$newDate,$target);return['before'=>$before,'after'=>$after,'updated_departments'=>$n,'culto_isolated'=>$clone];}\n"""
s=one(s,anchor,insert+anchor,'api helpers')
old=" if($action!=='delete')throw new RuntimeException('Ação inválida.');\n $ig=trim((string)($b['igreja_id']??''));$date=mse_valid_date(trim((string)($b['data']??'')),'Data da escala');$cultoRaw=$b['culto_id']??null;$cultoId=$cultoRaw===null||trim((string)$cultoRaw)===''?null:trim((string)$cultoRaw);\n if($ig===''||$date==='')throw new RuntimeException('Escala inválida.');$row=mse_one($ig,$date,$cultoId);if(!$row)throw new RuntimeException('A escala selecionada não existe mais. Atualize a lista.');\n if(trim((string)($b['confirmation']??''))!=='EXCLUIR')throw new RuntimeException('Digite EXCLUIR para confirmar a exclusão.');"
new=" $ig=trim((string)($b['igreja_id']??''));$date=mse_valid_date(trim((string)($b['data']??'')),'Data da escala');$cultoRaw=$b['culto_id']??null;$cultoId=$cultoRaw===null||trim((string)$cultoRaw)===''?null:trim((string)$cultoRaw);\n if($ig===''||$date==='')throw new RuntimeException('Escala inválida.');$row=mse_one($ig,$date,$cultoId);if(!$row)throw new RuntimeException('A escala selecionada não existe mais. Atualize a lista.');\n if($action==='edit'){$nd=mse_valid_date(trim((string)($b['new_date']??'')),'Nova data');if($nd==='')throw new RuntimeException('Informe a nova data.');$nn=trim((string)($b['new_name']??''));$nt=mse_valid_time(trim((string)($b['new_time']??'')));$ed=mse_edit_group($ig,$date,$cultoId,$nd,$nn,$nt,$row);try{audit((string)($caller['id']??''),'master_edit_complete_scale','escalas',['igreja_id'=>$ig,'before'=>['data'=>$date,'culto_id'=>$cultoId,'nome'=>$row['culto_nome']??null,'horario'=>$row['horario']??null],'after'=>['data'=>$nd,'culto_id'=>$ed['after']['culto_id']??null,'nome'=>$ed['after']['culto_nome']??$nn,'horario'=>$ed['after']['horario']??$nt]],'warning');}catch(Throwable$e){}out(['data'=>['success'=>true,'edited'=>$ed],'error'=>null]);}\n if($action!=='delete')throw new RuntimeException('Ação inválida.');\n if(trim((string)($b['confirmation']??''))!=='EXCLUIR')throw new RuntimeException('Digite EXCLUIR para confirmar a exclusão.');"
s=one(s,old,new,'api action')
p.write_text(s,encoding='utf-8')

