editjs="""function openEdit(x){editing=x;$('editName').value=(x.culto_nome&&x.culto_nome!=='Escala sem culto')?x.culto_nome:'';$('editDate').value=x.data||'';$('editTime').value=x.horario?String(x.horario).slice(0,5):'';$('editModal').classList.add('open')}function closeEdit(){if(!busy){editing=null;$('editModal').classList.remove('open')}}async function saveEdit(){if(!editing||busy)return;const name=$('editName').value.trim(),date=$('editDate').value,time=$('editTime').value;if(!name||!date){alert('Informe nome e data.');return}if(!confirm(`Editar esta escala completa?\\n\\n${editing.culto_nome||'Escala'} ${fmt(editing.data)} → ${name} ${fmt(date)} ${time}`))return;busy=true;try{await api({action:'edit',igreja_id:editing.igreja_id,data:editing.data,culto_id:editing.culto_id,new_name:name,new_date:date,new_time:time});closeEdit();msg('Escala alterada. Pessoas, funções e confirmações foram preservadas.','ok');await load()}catch(e){msg(e.message,'err')}finally{busy=false;render()}}"""
